def rle(s):
    if not s:
        return ''
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1] + str(count))
            count = 1
    result.append(s[-1] + str(count))
    return ''.join(result)

def balanced(s):
    """Return True if brackets ()[]{} in s are correctly nested and closed, else False.
    Other characters are ignored."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set('([{')
    for char in s:
        if char in opens:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
    return not stack

def to_base(n, b):
    if not (2 <= b <= 16):
        raise ValueError("base must be between 2 and 16")
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    out = ""
    while n > 0:
        out = digits[n % b] + out
        n //= b
    return out
